describe('Form Data Persistence on Navigation', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/form');
    cy.clearLocalStorage();
  });

  it('should persist form data when navigating away and returning', () => {
    // Fill out the form
    cy.get('input[name="firstName"]').type('John');
    cy.get('input[name="lastName"]').type('Doe');
    cy.get('input[name="email"]').type('john@example.com');
    cy.get('textarea[name="message"]').type('This is a test message');

    // Verify data is entered
    cy.get('input[name="firstName"]').should('have.value', 'John');
    cy.get('input[name="lastName"]').should('have.value', 'Doe');
    cy.get('input[name="email"]').should('have.value', 'john@example.com');
    cy.get('textarea[name="message"]').should('have.value', 'This is a test message');

    // Navigate away
    cy.visit('http://localhost:3000/other-page');

    // Navigate back to form
    cy.visit('http://localhost:3000/form');

    // Verify form data persists
    cy.get('input[name="firstName"]').should('have.value', 'John');
    cy.get('input[name="lastName"]').should('have.value', 'Doe');
    cy.get('input[name="email"]').should('have.value', 'john@example.com');
    cy.get('textarea[name="message"]').should('have.value', 'This is a test message');
  });

  it('should persist partial form data and allow completion after navigation', () => {
    // Fill out only some fields
    cy.get('input[name="firstName"]').type('Jane');
    cy.get('input[name="email"]').type('jane@example.com');

    // Navigate away using browser back button
    cy.go('back');

    // Navigate forward
    cy.go('forward');

    // Verify partial data persists
    cy.get('input[name="firstName"]').should('have.value', 'Jane');
    cy.get('input[name="email"]').should('have.value', 'jane@example.com');

    // Complete the remaining fields
    cy.get('input[name="lastName"]').type('Smith');
    cy.get('textarea[name="message"]').type('Completing the form');

    // Verify all data is present
    cy.get('input[name="firstName"]').should('have.value', 'Jane');
    cy.get('input[name="lastName"]').should('have.value', 'Smith');
    cy.get('input[name="email"]').should('have.value', 'jane@example.com');
    cy.get('textarea[name="message"]').should('have.value', 'Completing the form');

    // Submit form
    cy.get('button[type="submit"]').click();
    cy.get('.success-message').should('be.visible');
  });

  it('should clear persisted data after successful form submission', () => {
    // Fill out the form
    cy.get('input[name="firstName"]').type('Bob');
    cy.get('input[name="lastName"]').type('Johnson');
    cy.get('input[name="email"]').type('bob@example.com');
    cy.get('textarea[name="message"]').type('Test submission');

    // Submit the form
    cy.get('button[type="submit"]').click();
    cy.get('.success-message').should('be.visible');

    // Navigate away and back
    cy.visit('http://localhost:3000/other-page');
    cy.visit('http://localhost:3000/form');

    // Verify form is cleared after successful submission
    cy.get('input[name="firstName"]').should('have.value', '');
    cy.get('input[name="lastName"]').should('have.value', '');
    cy.get('input[name="email"]').should('have.value', '');
    cy.get('textarea[name="message"]').should('have.value', '');
  });

  it('should handle form data persistence with special characters and long text', () => {
    const specialText = 'Test@#$%^&*()_+-=[]{}|;:,.<>?/~`';
    const longText = 'a'.repeat(500);

    cy.get('input[name="firstName"]').type(specialText);
    cy.get('textarea[name="message"]').type(longText);

    // Navigate away
    cy.visit('http://localhost:3000/other-page');
    cy.visit('http://localhost:3000/form');

    // Verify special characters and long text persist
    cy.get('input[name="firstName"]').should('have.value', specialText);
    cy.get('textarea[name="message"]').should('have.value', longText);
  });
});
